<?php
declare(strict_types=1);
namespace Plugins\Modules\FlashSale\Http\Controllers;
use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\View\View;
use Illuminate\Http\RedirectResponse;
class FlashSaleController extends Controller {
 public function index():View{return view('flash-sale::index',['sales'=>DB::table('flash_sales')->leftJoin('courses','courses.id','=','flash_sales.course_id')->select('flash_sales.*','courses.title as course_title')->latest('flash_sales.id')->paginate(25),'courses'=>DB::table('courses')->whereNull('deleted_at')->orderBy('title')->get(),'settings'=>DB::table('flash_sale_settings')->first()]);}
 public function store(Request $r):RedirectResponse{$v=$this->validated($r);DB::table('flash_sales')->insert($v+['is_published'=>$r->boolean('is_published'),'is_active'=>$r->boolean('is_active'),'created_at'=>now(),'updated_at'=>now()]);return back()->with('status','Campaign created.');}
 public function update(Request $r,int $sale):RedirectResponse{$v=$this->validated($r);DB::table('flash_sales')->where('id',$sale)->update($v+['is_published'=>$r->boolean('is_published'),'is_active'=>$r->boolean('is_active'),'updated_at'=>now()]);return back()->with('status','Campaign updated.');}
 public function toggle(int $sale):RedirectResponse{$row=DB::table('flash_sales')->where('id',$sale)->first();abort_unless($row,404);DB::table('flash_sales')->where('id',$sale)->update(['is_active'=>!$row->is_active,'updated_at'=>now()]);return back()->with('status','Campaign active state changed.');}
 public function destroy(int $sale):RedirectResponse{DB::table('flash_sales')->where('id',$sale)->delete();return back()->with('status','Campaign deleted.');}
 public function settings(Request $r):RedirectResponse{$v=$r->validate(['page_enabled'=>['required','boolean'],'page_title'=>['required','string','max:160']]);DB::table('flash_sale_settings')->updateOrInsert(['id'=>1],$v+['created_at'=>now(),'updated_at'=>now()]);return back()->with('status','Page settings saved.');}
 public function publicIndex():View{$s=DB::table('flash_sale_settings')->first();abort_unless($s&&$s->page_enabled,404);$sales=DB::table('flash_sales')->join('courses','courses.id','=','flash_sales.course_id')->where('flash_sales.is_published',1)->where('flash_sales.is_active',1)->where('flash_sales.starts_at','<=',now())->where('flash_sales.ends_at','>',now())->where('courses.status','published')->select('flash_sales.*','courses.title as course_title','courses.slug as course_slug','courses.price as course_price')->orderBy('flash_sales.ends_at')->get()->map(function($x){$p=(float)$x->course_price;$d=$x->discount_type==='percent'?$p*(float)$x->discount_value/100:(float)$x->discount_value;$x->sale_price=max(0,$p-min($p,$d));return $x;});return view('flash-sale::public',['settings'=>$s,'sales'=>$sales,'currency'=>strtoupper((string)config('lms.default_currency','BDT'))]);}
 private function validated(Request $r):array{$v=$r->validate(['course_id'=>['required','integer','exists:courses,id'],'title'=>['required','string','max:160'],'discount_type'=>['required','in:percent,fixed'],'discount_value'=>['required','numeric','gt:0','max:1000000'],'starts_at'=>['required','date'],'ends_at'=>['required','date','after:starts_at']]);if($v['discount_type']==='percent'&&(float)$v['discount_value']>100)abort(422,'Percent discount cannot exceed 100.');return $v;}
}